import SwiftUI

/// A display-only streak summary. The model supplies every state it shows.
struct StreakIndicator: View {
    @Environment(\.streak) private var streak

    var body: some View {
        if let status = streak?.status, status.current > 0 {
            HStack(spacing: 5) {
                Image(systemName: status.isOnVacation ? "beach.umbrella.fill" : "flame.fill")
                    .dsFixedFont(.system(size: 15, weight: .semibold))
                    .foregroundStyle(status.isOnVacation ? DS.Colors.mint : DS.Colors.limitAmber)
                Text("\(status.current)")
                    .dsFixedFont(.system(size: 15, weight: .bold))
                    .foregroundStyle(.white)
                if status.riskDeadline != nil {
                    Circle()
                        .fill(DS.Colors.limitAmber)
                        .frame(width: 6, height: 6)
                }
            }
            .fixedSize(horizontal: true, vertical: false)
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(accessibilityLabel(for: status))
            .transaction { $0.animation = nil }
        }
    }

    private func accessibilityLabel(for status: StreakStatus) -> String {
        var label = "\(status.current) day streak"
        if status.riskDeadline != nil { label += ", at risk" }
        if status.isOnVacation { label += ", on vacation" }
        return label
    }
