           runningQuickStart.start.addingTimeInterval(TimeInterval(runningQuickStart.durationMinutes) * 60) > now {
            starts.insert(runningQuickStart.start)
        }
        return starts.sorted()
    }

    static func noScheduledWindowLeft(
        schedules: [BlockingSchedule], schedulesWithTargets: Set<UUID>,
        blockRunning: Bool, now: Date, calendar: Calendar
    ) -> Bool {
        guard !blockRunning else { return false }
        let today = calendar.startOfDay(for: now)
        let weekday = calendar.component(.weekday, from: today)
        return !schedules.contains { schedule in
            guard schedulesWithTargets.contains(schedule.id), schedule.activeDays.contains(weekday),
                  schedule.startHour * 60 + schedule.startMinute != schedule.endHour * 60 + schedule.endMinute,
                  let start = calendar.date(bySettingHour: schedule.startHour, minute: schedule.startMinute,
                                            second: 0, of: today) else { return false }
            return calendar.isDate(start, inSameDayAs: today) && start > now
        }
    }

    static func evaluate(_ input: StreakInput) -> StreakStatus {
        let calendar = input.calendar
        let today = calendar.startOfDay(for: input.now)
        var run = 0
        var earliestDeadline: Date?
        var usedPasses: [String: Int] = [:]
        var usedRescues: Set<Date> = []
        let rescues = Set(input.rescueStarts).sorted()
        var day = BadgeEngine.date(fromDayStamp: input.log.firstDay, calendar: calendar) ?? today
        while day <= today {
            guard let nextDay = calendar.date(byAdding: .day, value: 1, to: day),
                  let deadline = calendar.date(byAdding: .day, value: StreakConfig.rescueWindowDays + 1, to: day)
            else { break }
            let stamp = BadgeEngine.dayStamp(for: day, calendar: calendar)
            let week = BadgeEngine.dayStamp(for: weekStart(for: day, calendar: calendar), calendar: calendar)
            let scheduled = input.log.scheduledDays.contains(stamp)
            let counts = input.blockedDays.contains(stamp) || input.log.limitKeptDays.contains(stamp)
                || (day < today && input.liveSourceStart.map { $0 < nextDay } == true)
            let vacationTouched = VacationRules.touchesDay(day, periods: input.vacations, calendar: calendar)
            let hasPass = usedPasses[week, default: 0] < input.log.weekPassAllowance[week, default: 0]

            if counts {
                run += 1
            } else if run > 0, scheduled, !vacationTouched {
                if day == today {
                    if earliestDeadline == nil, !hasPass, input.noScheduledWindowLeftToday, input.liveSourceStart == nil {
                        earliestDeadline = deadline
                    }
                } else if hasPass {
                    usedPasses[week, default: 0] += 1
                } else if let rescue = rescues.first(where: { $0 >= nextDay && $0 < deadline && !usedRescues.contains($0) }) {
                    usedRescues.insert(rescue)
                } else if input.now < deadline {
                    earliestDeadline = min(earliestDeadline ?? deadline, deadline)
                } else {
                    run = 0
                }
            }
            day = nextDay
        }
        return StreakStatus(current: run, riskDeadline: earliestDeadline,
                            isOnVacation: VacationRules.active(in: input.vacations, at: input.now) != nil)
    }
}
