import SwiftUI

// MARK: - HomeQuickStartMenuSheet
//
// What the chevron on Home's idle Quick Start bar opens: the three ways to set
// something up, for the taps the one-tap bar cannot cover.
//
//   • Edit Quick Start      → the Quick Start panel
//   • New scheduled block   → the create-block sheet
//   • New daily limit       → the limit-create sheet
//
// Every row opens a panel on Home itself, so no row acts here and nothing
// switches tabs. A row hands its choice to `onSelect` and dismisses;
// `HomeView` holds the choice until this sheet has finished dismissing and
// only then presents, because two sheets crossing would collide.

/// Which row of the menu the user picked, and therefore which panel `HomeView`
/// presents once this sheet is out of the way. `Identifiable` so it can drive
/// Home's single `.sheet(item:)`, the idiom that keeps SwiftUI from ever
/// observing a half-applied presentation.
enum QuickStartMenuChoice: Identifiable {
    /// The Quick Start panel: apps, purpose, duration and Start, on Home.
    case customize
    /// The create-block sheet, on Home.
    case newBlock
    /// The daily-limit create sheet, on Home.
    case newLimit

    var id: String {
        switch self {
        case .customize: return "customize"
        case .newBlock: return "new-block"
        case .newLimit: return "new-limit"
        }
    }
}

struct HomeQuickStartMenuSheet: View {
    /// The picked row. `HomeView` stashes it rather than running it.
    let onSelect: (QuickStartMenuChoice) -> Void

    @Environment(\.dismiss) private var dismiss

    var body: some View {
        menuCard
            .padding(.horizontal, 16)
            .padding(.top, 27)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
            .background(DS.Colors.pageBackground.ignoresSafeArea())
            // Measured on the simulator, not derived from the card: iOS adds
            // the bottom safe area to a height detent, so 196 is what leaves
            // the design's ~40pt of sheet below the card.
            .presentationDetents([.height(196)])
            .presentationDragIndicator(.visible)
    }

    /// The three rows share one rounded card, split by separators.
    private var menuCard: some View {
        VStack(spacing: 0) {
            menuRow(
                title: "Edit Quick Start",
                icon: quickStartIcon,
                choice: .customize
            )
            separator
            menuRow(
                title: "New scheduled block",
                icon: neutralIcon(symbol: "calendar"),
                choice: .newBlock
            )
            separator
            menuRow(
                title: "New daily limit",
                icon: neutralIcon(symbol: "hourglass"),
                choice: .newLimit
            )
        }
        .background(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .fill(DS.Colors.groupedSurface)
        )
    }

    private func menuRow<Icon: View>(title: String, icon: Icon, choice: QuickStartMenuChoice) -> some View {
        Button {
            Haptics.fire(.tap)
            onSelect(choice)
            dismiss()
        } label: {
            HStack(spacing: Self.iconToTitleSpacing) {
                icon
                    // A fixed width so the three titles line up under each
                    // other whatever each icon measures.
                    .frame(width: Self.iconColumnWidth)
                Text(title)
                    .font(.system(size: 17))
                    .foregroundStyle(.white)
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)
                Spacer(minLength: 8)
                Image(systemName: "chevron.right")
                    .font(.system(size: 16, weight: .semibold))
                    .foregroundStyle(Self.chevronColor)
                    .accessibilityHidden(true)
            }
            .padding(.leading, Self.iconLeadingInset)
            .padding(.trailing, 16)
            .frame(height: Self.rowHeight)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }

    /// Row 1 wears the Quick Start bar's play glyph, so it reads as the same
    /// feature the bar starts.
    private var quickStartIcon: some View {
        Circle()
            .fill(DS.Colors.accent)
            .frame(width: 27, height: 27)
            .overlay(
                Image(systemName: "play.fill")
                    .font(.system(size: 11))
                    .foregroundStyle(.white)
            )
    }

    private func neutralIcon(symbol: String) -> some View {
        Image(systemName: symbol)
            .font(.system(size: 20))
            .foregroundStyle(Self.neutralIconColor)
    }

    /// Starts where the titles start, so the line reads as belonging to the
    /// text and not the icons. A 1pt line in the system separator color
    /// rather than a `Divider()`, whose hairline is lighter than the design.
    private var separator: some View {
        Rectangle()
            .fill(Color(.separator))
            .frame(height: 1)
            .padding(.leading, Self.separatorLeadingInset)
    }

    private static let rowHeight: CGFloat = 54
    private static let iconLeadingInset: CGFloat = 17
    private static let iconColumnWidth: CGFloat = 28
    private static let iconToTitleSpacing: CGFloat = 15
    private static let separatorLeadingInset = iconLeadingInset + iconColumnWidth + iconToTitleSpacing
    /// The mock's #DEDEDE. `DS.Colors.textSecondary` renders about #9F9FA5 on
    /// the card, far dimmer, so this file declares the literal.
    private static let neutralIconColor = Color(red: 0xDE / 255, green: 0xDE / 255, blue: 0xDE / 255)
    /// The mock's #818082. `DS.Colors.textSecondary` renders #9F9FA5 on the
    /// card, visibly brighter, and no token lands on this gray, so this file
    /// declares the literal.
    private static let chevronColor = Color(red: 0x81 / 255, green: 0x80 / 255, blue: 0x82 / 255)
}

