// ============================================================================
// Haptics: centralized, host-UI-only tactile feedback
// ============================================================================
//
// Single source of truth for haptic feedback across the app. Every button /
// row / control routes through this small vocabulary instead of allocating
// its own UIKit generator, so the feel stays consistent app-wide.
//
// USAGE:
//
//   Imperative (inside a Button action closure):
//       Button {
//           Haptics.fire(.tap)
//           openSheet()
//       } label: { ... }
//
//   Declarative (on a control with NO action closure, e.g. NavigationLink):
//       NavigationLink { Destination() } label: { Row() }
//           .hapticTap()              // defaults to .tap
//
// LAYERING:
//
//   This file lives in Sources/App (host-app targets ScreenTime + ScreenTimeUI
//   only), NOT Sources/Shared. App extensions cannot drive the Taptic Engine,
//   so a UIKit haptic helper has no place in the shared layer.
//
// VOCABULARY (5 roles → standard generators):
//
//   .tap        UIImpactFeedbackGenerator(.light): open a sheet/picker, push
//                                                      a screen, acknowledge a
//                                                      non-committal tap
//   .selection  UISelectionFeedbackGenerator: tabs, segmented controls,
//                                                      picker/list selection rows
//   .success    UINotificationFeedbackGenerator(.success): a positive action
//                                                      that actually committed
//   .warning    UINotificationFeedbackGenerator(.warning): a destructive action
//                                                      that actually committed
//   .error      UINotificationFeedbackGenerator(.error): an operation failed
//
// All UIKit feedback generators honor the system "System Haptics" setting
// (Settings ▸ Sounds & Haptics) automatically, so there is no separate opt-out
// to maintain here.
// ============================================================================

/// Semantic haptic roles mapped to the platform's standard feedback
/// generators. Pick the role by what the control *means*, not where it lives.
enum Haptic {
    /// Light impact: navigation / acknowledge (open a sheet, push a screen).
    case tap
    /// Selection change: tabs, segmented controls, picker/list selection rows.
    case selection
    /// A meaningful positive action that actually committed (start, save, add).
    case success
    /// A destructive action that actually committed (delete, stop, replace).
    case warning
    /// An operation failed (save/delete/encode failed, authorization denied).
    case error
}

/// Fires haptic feedback through cached, reused UIKit generators. Generators
/// are reference types, so a single shared instance per family avoids the
/// per-fire allocation a few call sites used to do inline.
enum Haptics {

    private static let lightImpact = UIImpactFeedbackGenerator(style: .light)
    private static let selectionGenerator = UISelectionFeedbackGenerator()
    private static let notification = UINotificationFeedbackGenerator()

    /// Fire the feedback for a semantic role. No-op on the Simulator (UIKit
    /// feedback generators do nothing there): haptics require a device.
    static func fire(_ haptic: Haptic) {
        switch haptic {
        case .tap:
            lightImpact.impactOccurred()
        case .selection:
            selectionGenerator.selectionChanged()
        case .success:
            notification.notificationOccurred(.success)
        case .warning:
            notification.notificationOccurred(.warning)
        case .error:
            notification.notificationOccurred(.error)
        }
    }

    /// Creates the three generators and prepares the Taptic Engine ahead of the
